//#endregion
//#region src/game/routeGraph.ts
const graphCache = /* @__PURE__ */ new WeakMap();
function graphFor(level) {
	const cached = graphCache.get(level);
	if (cached) return cached;
	const nodesById = new Map(level.nodes.map((node) => [node.id, node]));
	const roadsById = new Map(level.roads.map((road) => [road.id, road]));
	const roadsByNode = /* @__PURE__ */ new Map();
	for (const node of level.nodes) roadsByNode.set(node.id, []);
	for (const road of level.roads) {
		roadsByNode.get(road.from)?.push(road);
		roadsByNode.get(road.to)?.push(road);
	}
	const graph = {
		nodesById,
		roadsById,
		roadsByNode
	};
	graphCache.set(level, graph);
	return graph;
}
function nodeById(level, id) {
	const node = graphFor(level).nodesById.get(id);
	if (!node) throw new Error(`Unknown junction: ${id}`);
	return node;
}
function roadById(level, id) {
	const road = graphFor(level).roadsById.get(id);
	if (!road) throw new Error(`Unknown road: ${id}`);
	return road;
}
function currentNodeId(route) {
	return route.nodeIds[route.nodeIds.length - 1];
}
function totalDistanceKm(level, route) {
	const total = route.roadIds.reduce((sum, id) => sum + roadById(level, id).distanceKm, 0);
	return Math.round(total * 100) / 100;
}

//#endregion
//#region src/game/routeEvaluation.ts
/** `{km}` in level copy becomes the route's distance. */
function fillCopy(copy, totalKm) {
	const km = totalKm.toFixed(2);
	return {
		title: copy.title,
		message: copy.message.replaceAll("{km}", km)
	};
}
function visitedNodes(route, nodeIds) {
	return route.nodeIds.some((id) => nodeIds.includes(id));
}
/** Distinct junctions of a given type on the route — pigeon hotspots and such. */
function countNodeType(level, route, nodeType) {
	const seen = /* @__PURE__ */ new Set();
	for (const id of route.nodeIds) if (nodeById(level, id).type === nodeType) seen.add(id);
	return seen.size;
}
function usedClosedRoad(level, route) {
	return route.roadIds.some((id) => roadById(level, id).closed === true);
}
function countSurface(level, route, surface) {
	return route.roadIds.filter((id) => (roadById(level, id).surface ?? "road") === surface).length;
}
function hasRepeatedRoad(route) {
	return new Set(route.roadIds).size !== route.roadIds.length;
}
/** One objective, evaluated. Failure copy is resolved here, not later. */
function evaluateObjective(objective, context) {
	const { level, route, totalKm, isEmpty, endsAtFinish } = context;
	switch (objective.kind) {
		case "start": return {
			kind: objective.kind,
			label: `Start at ${nodeById(level, level.startNodeId).label}`,
			detail: objective.detail,
			state: "passed"
		};
		case "finish": {
			const finish = nodeById(level, level.finishNodeId).label;
			return {
				kind: objective.kind,
				label: `Finish at ${finish}`,
				detail: endsAtFinish ? objective.detail : isEmpty ? "Nobody has set off yet." : `Currently ending at ${nodeById(level, currentNodeId(route)).label}.`,
				state: endsAtFinish ? "passed" : "incomplete"
			};
		}
		case "distance": {
			const tooLong = totalKm > objective.maxKm;
			const tooShort = totalKm < objective.minKm;
			return {
				kind: objective.kind,
				label: `Cover ${objective.minKm}–${objective.maxKm} km`,
				detail: `${totalKm.toFixed(2)} km so far.`,
				state: tooLong ? "failed" : tooShort ? "incomplete" : "passed",
				fail: tooLong ? fillCopy(objective.tooLong, totalKm) : fillCopy(objective.tooShort, totalKm),
				stat: {
					label: "Distance",
					value: `${totalKm.toFixed(2)} km`
				}
			};
		}
		case "visit": {
			const visited = visitedNodes(route, objective.nodeIds);
			return {
				kind: objective.kind,
				label: `Visit ${objective.what}`,
				detail: visited ? objective.done : objective.pending,
				state: visited ? "passed" : "incomplete",
				fail: fillCopy(objective.missed, totalKm),
				stat: {
					label: objective.what.replace(/^the /, ""),
					value: visited ? "Visited" : "Missed"
				}
			};
		}
		case "avoid-closed": {
			const closed = usedClosedRoad(level, route);
			return {
				kind: objective.kind,
				label: "Avoid the closed road",
				detail: closed ? "You have routed everyone through a closure." : "Nothing shut on this route.",
				state: closed ? "failed" : "passed",
				fail: fillCopy(objective.fail, totalKm)
			};
		}
		case "avoid-surface": {
			const count = countSurface(level, route, objective.surface);
			return {
				kind: objective.kind,
				label: `Stay off ${objective.what}`,
				detail: count === 0 ? `No ${objective.what.replace(/^the /, "")} on this route.` : `${count} stretch${count === 1 ? "" : "es"} of ${objective.what}.`,
				state: count > 0 ? "failed" : "passed",
				fail: fillCopy(objective.fail, totalKm)
			};
		}
		case "max-node-type": {
			const count = countNodeType(level, route, objective.nodeType);
			return {
				kind: objective.kind,
				label: objective.label ?? `Pass no more than ${objective.limit} ${objective.what}`,
				detail: `${count} on the route.`,
				state: count > objective.limit ? "failed" : "passed",
				fail: fillCopy(objective.fail, totalKm),
				stat: {
					label: objective.what,
					value: String(count)
				}
			};
		}
		case "no-repeat": {
			const repeated = hasRepeatedRoad(route);
			return {
				kind: objective.kind,
				label: "Never use the same road twice",
				detail: repeated ? "A road is repeated." : "Every road used once.",
				state: repeated ? "failed" : "passed",
				fail: fillCopy(objective.fail, totalKm)
			};
		}
	}
}
/**
* The whole rule set, driven by the level's declared objectives. Objectives
* that cannot yet be decided stay "incomplete" rather than showing a premature
* failure.
*/
function evaluateRoute(level, route) {
	const totalKm = totalDistanceKm(level, route);
	const isEmpty = route.roadIds.length === 0;
	const endsAtFinish = !isEmpty && currentNodeId(route) === level.finishNodeId;
	const context = {
		level,
		route,
		totalKm,
		isEmpty,
		endsAtFinish
	};
	const seenKinds = /* @__PURE__ */ new Map();
	const stats = [];
	let stranded;
	const objectives = level.objectives.map((objective) => {
		const { stat, ...result } = evaluateObjective(objective, context);
		if (stat) stats.push(stat);
		const count = (seenKinds.get(objective.kind) ?? 0) + 1;
		seenKinds.set(objective.kind, count);
		const id = count === 1 ? objective.kind : `${objective.kind}-${count}`;
		if (objective.kind === "visit" && objective.stranded && !isEmpty && !endsAtFinish && objective.nodeIds.includes(currentNodeId(route))) stranded = fillCopy(objective.stranded, totalKm);
		return {
			id,
			...result
		};
	});
	return {
		totalDistanceKm: totalKm,
		isEmpty,
		endsAtFinish,
		objectives,
		stats,
		stranded,
		success: !isEmpty && objectives.every((o) => o.state === "passed")
	};
}

